const fs = require('fs');

function extract(filename) {
  const buf = fs.readFileSync(filename);
  // Basic ELF parsing to extract loadable segments or sections, or whole file loaded at 0x400000
  // Let's check program headers
  const e_phoff = buf.readBigUInt64LE(0x20);
  const e_phentsize = buf.readUInt16LE(0x36);
  const e_phnum = buf.readUInt16LE(0x38);

  const result = {};
  const baseAddr = 0x400000;

  // If we map loadable segments or the whole file:
  // Let's parse program headers for LOAD segments
  for (let i = 0; i < e_phnum; i++) {
    const phoff = Number(e_phoff) + i * e_phentsize;
    const p_type = buf.readUInt32LE(phoff);
    if (p_type === 1) { // PT_LOAD
      const p_offset = Number(buf.readBigUInt64LE(phoff + 0x08));
      const p_vaddr = Number(buf.readBigUInt64LE(phoff + 0x10));
      const p_filesz = Number(buf.readBigUInt64LE(phoff + 0x20));
      const p_memsz = Number(buf.readBigUInt64LE(phoff + 0x28));

      const startAddr = baseAddr + p_vaddr;
      for (let offset = 0; offset < p_filesz; offset += 4) {
        if (p_offset + offset + 4 <= buf.length) {
          const val = buf.readInt32LE(p_offset + offset);
          result[(startAddr + offset).toString()] = val;
        }
      }
    }
  }

  console.log(JSON.stringify(result, null, 2));
}

extract(process.argv[2] || 'a.out');
